# Section A of the JAMB UTME Biology syllabus: variety of organisms.
# Living things and their characteristics, the cell and its environment,
# levels of organisation, the kingdoms (Monera, Protista, Fungi, Plantae,
# Animalia), and structural, functional and behavioural adaptations.
# Key written first; the build shuffles.

ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 2, "Cell organelles", "Which organelle has a double membrane whose inner layer is folded into cristae?",
      ["Mitochondrion", "Ribosome", "Golgi apparatus", "Lysosome"],
      "The folded inner membrane of the mitochondrion carries the enzymes of aerobic respiration. Ribosomes have no membrane at all."),
    S(1, 2, "Plant and animal cells", "Which structure is found in an animal cell but not in the cells of flowering plants?",
      ["Centrioles", "Plasma (cell) membrane", "Ribosomes", "Mitochondria"],
      "Animal cells have a pair of centrioles near the nucleus; flowering plant cells divide without them. Every living cell has a membrane and ribosomes."),
    S(1, 1, "Protista", "Paramecium moves through water by the beating of its:",
      ["Cilia", "Flagellum", "Pseudopodia", "Setae"],
      "Paramecium is covered in short hair-like cilia that beat in waves. Euglena uses a single flagellum and Amoeba flows on pseudopodia."),
    S(1, 1, "Levels of organisation", "A group of similar cells that carry out one function together is called:",
      ["A tissue", "An organ", "A system", "A colony"],
      "Cells form tissues, tissues form organs and organs form systems. A colony, as in Volvox, is a group of similar cells living together without being organised into tissues."),
    S(1, 2, "Fungi", "Rhizopus, the black mould on stale bread, reproduces asexually by:",
      ["Spores formed in sporangia", "Budding off small cells", "Binary fission of hyphae", "Zygospores from two strains"],
      "Rhizopus forms sporangia on upright hyphae and releases spores that grow into new mycelia. Zygospores come from conjugation of two strains, which is sexual."),
    S(1, 2, "Arthropoda", "Which feature is found in every member of the phylum Arthropoda?",
      ["Jointed appendages", "Three pairs of legs", "Two pairs of wings", "A pair of antennae"],
      "All arthropods have jointed limbs and a chitin exoskeleton. Three pairs of legs and wings belong to insects only, and spiders have no antennae."),
    S(1, 2, "Osmosis", "Salting fish before drying it keeps the fish from going bad mainly because the salt:",
      ["Draws water out of microbes by osmosis", "Raises the temperature of the fish", "Adds oxygen that microbes cannot use", "Makes microbes take in more water"],
      "The salty surface is hypertonic to the cells of bacteria and fungi, so water leaves them by osmosis and they cannot grow. Sugar preserves jam in the same way."),
    S(1, 2, "Adaptation", "A thick waxy cuticle on the leaves of savanna plants mainly helps them to:",
      ["Reduce water loss", "Absorb more light", "Trap insect prey", "Take in more air"],
      "A waxy cuticle cuts down evaporation from the leaf surface, a structural adaptation to the long dry season. It does nothing to increase light or gas uptake."),

    # ---------- Practice Test 2 ----------
    S(2, 1, "Cell organelles", "What is the main function of the ribosomes in a cell?",
      ["Protein synthesis", "Storing starch", "Releasing energy", "Dividing the nucleus"],
      "Ribosomes join amino acids into proteins. Energy release is the work of the mitochondria, and starch is stored in plastids."),
    S(2, 2, "Protista", "Euglena has been placed with both plants and animals because it:",
      ["Has chloroplasts and moves freely", "Has a cellulose wall and cilia", "Feeds on bacteria and has true roots", "Makes spores and has a skeleton"],
      "Euglena photosynthesises with chloroplasts like a plant but swims with a flagellum and can feed heterotrophically in the dark like an animal."),
    S(2, 2, "Bryophytes", "A moss plant lacks which of these?",
      ["True vascular tissue", "Chlorophyll", "Rhizoids", "Spore-bearing capsules"],
      "Mosses have no xylem or phloem, which keeps them small and in damp places. They do have chlorophyll, rhizoids for anchorage and capsules that release spores."),
    S(2, 1, "Annelida", "The earthworm belongs to the phylum:",
      ["Annelida", "Nematoda", "Platyhelminthes", "Arthropoda"],
      "Annelids have a body divided into ring-like segments, as in the earthworm. Roundworms (Nematoda) are not segmented and flatworms (Platyhelminthes) are flattened."),
    S(2, 1, "Classification", "In the scientific name of the housefly, Musca domestica, the word domestica is the name of the:",
      ["Species", "Genus", "Family", "Subspecies"],
      "In binomial nomenclature the first word, with a capital letter, is the genus and the second word is the species."),
    S(2, 2, "Osmosis", "A plant cell placed in a concentrated salt solution will become:",
      ["Plasmolysed", "Swollen", "Burst", "Fully turgid"],
      "Water leaves the cell by osmosis into the stronger solution, so the protoplast shrinks away from the wall. The cellulose wall stops a plant cell from bursting in water."),
    S(2, 1, "Aves", "Which feature is found only in birds among living animals?",
      ["Feathers", "Lungs", "A beak-like mouth", "Hard-shelled eggs"],
      "Only birds have feathers. Tortoises have beak-like mouths, and reptiles also lay eggs with shells."),
    S(2, 2, "Coelenterata", "Hydra has a body wall made of only two layers of cells, so it is described as:",
      ["Diploblastic", "Triploblastic", "Bilaterally symmetrical", "Segmented"],
      "Coelenterates have an outer ectoderm and inner endoderm with jelly-like mesogloea between. Flatworms and all higher animals are triploblastic."),
    # ---------- Drill only ----------
    S(0, 1, "Living things", "A candle flame uses oxygen and gives out heat. Which feature of living things does it lack?",
      ["Reproduction", "Release of energy", "Use of oxygen", "Giving off carbon(IV) oxide"],
      "Burning, like respiration, uses oxygen, releases energy and gives off carbon(IV) oxide. A flame cannot reproduce, grow from within or respond as an organism does."),
    S(0, 1, "Cell organelles", "Which organelle contains enzymes that digest worn-out parts of the cell?",
      ["Lysosome", "Golgi body", "Centriole", "Nucleolus"],
      "Lysosomes are membrane sacs of digestive enzymes. The Golgi body packages substances for secretion and the nucleolus makes ribosomes."),
    S(0, 2, "Cell organelles", "In an animal cell, the centrioles help to:",
      ["Form the spindle in division", "Store food reserves", "Make proteins", "Control what enters the cell"],
      "Centrioles organise the spindle fibres that pull chromosomes apart during cell division. Most plant cells divide without them."),
    S(0, 1, "Cell structure", "Which part of a cell controls the passage of substances in and out?",
      ["Cell membrane", "Cell wall", "Nucleus", "Vacuole"],
      "The cell membrane is selectively permeable. A plant cell wall is fully permeable and only gives shape and support."),
    S(0, 1, "Protista", "Amoeba moves and captures its food by means of:",
      ["Pseudopodia", "Cilia", "Flagella", "Tentacles"],
      "Amoeba pushes out finger-like pseudopodia, which also flow round food particles to form food vacuoles."),
    S(0, 2, "Monera", "Blue-green algae are placed in the kingdom:",
      ["Monera", "Protista", "Fungi", "Plantae"],
      "Blue-green algae (cyanobacteria) are prokaryotes with no nuclear membrane, like bacteria, so they belong to Monera despite their colour."),
    S(0, 2, "Pteridophytes", "Ferns differ from mosses in having:",
      ["Vascular tissue", "Spores", "Chlorophyll", "A gametophyte stage"],
      "Ferns have xylem and phloem and true roots, stems and leaves. Both groups make spores, photosynthesise and have a gametophyte stage."),
    S(0, 2, "Spermatophytes", "Gymnosperms such as pines differ from flowering plants because their seeds:",
      ["Are not enclosed in a fruit", "Are carried in pods", "Have no food store inside them", "Are never wind dispersed"],
      "Gymnosperm means naked seed: the ovules sit exposed on cone scales. In flowering plants the ovule is enclosed in an ovary that becomes the fruit."),
    S(0, 1, "Monocots and dicots", "Which feature of a maize leaf shows that maize is a monocotyledon?",
      ["Parallel veins", "Net veins", "A broad blade", "A long petiole"],
      "Monocot leaves have parallel venation; dicots such as hibiscus have a network of veins. Maize also has one seed leaf and fibrous roots."),
    S(0, 1, "Platyhelminthes", "The tapeworm belongs to the phylum:",
      ["Platyhelminthes", "Annelida", "Nematoda", "Coelenterata"],
      "Tapeworms are flatworms with a flattened body and flame cells. Their chain of proglottids is not true segmentation like that of annelids."),
    S(0, 1, "Insecta", "How many pairs of legs does an adult insect have?",
      ["3", "4", "6", "8"],
      "Insects have three pairs, one on each segment of the thorax, so six legs in all. Spiders have four pairs."),
    S(0, 2, "Arachnida", "A spider differs from a housefly in having:",
      ["Four pairs of legs", "Three body parts", "A pair of antennae", "Wings on the thorax"],
      "Arachnids have four pairs of legs and two body parts, and no antennae or wings. The housefly, an insect, has three pairs of legs and three body parts."),
    S(0, 1, "Mollusca", "The giant African land snail belongs to the phylum:",
      ["Mollusca", "Arthropoda", "Annelida", "Echinodermata"],
      "Molluscs have a soft unsegmented body with a muscular foot and usually a shell. Echinoderms such as starfish are marine."),
    S(0, 2, "Amphibia", "A toad can take in oxygen through its skin because the skin is:",
      ["Thin, moist and full of capillaries", "Covered in dry horny scales like a lizard's", "Hard and full of keratin", "Thick and lined with fat"],
      "Amphibian skin is kept moist by mucus and has many capillaries, so gases dissolve and diffuse across it. Dry scaly skin, as in lizards, prevents this."),
    S(0, 1, "Mammalia", "Which pair of features is found in all mammals?",
      ["Hair and mammary glands", "Scales and gills", "Feathers and a beak", "Dry skin and shelled eggs"],
      "Mammals have hair and feed their young on milk from mammary glands. Even the egg-laying mammals have both."),
    S(0, 2, "Pisces", "In a fish such as Tilapia, the lateral line detects:",
      ["Vibrations in the water", "Light and shade", "Salt in the water", "Dissolved oxygen"],
      "The lateral line is a row of sense organs along each side that pick up pressure changes, helping the fish sense movement and keep in a shoal."),
    S(0, 1, "Diffusion", "Oxygen enters an Amoeba from the surrounding water by:",
      ["Diffusion", "Osmosis", "Active transport", "Phagocytosis"],
      "Oxygen is more concentrated in the water than in the cell, so it diffuses in across the membrane. Osmosis refers to water only."),
    S(0, 2, "Active transport", "Roots in a nutrient solution are given a poison that stops respiration. Their uptake of potassium ions stops, although water still enters. The ions were being taken up by:",
      ["Active transport", "Diffusion", "Osmosis", "Transpiration"],
      "Only active transport depends on energy from respiration, so stopping respiration stops it. Water enters by osmosis, which needs no energy from the cell."),
    S(0, 2, "Levels of organisation", "Volvox is an example of which level of organisation?",
      ["Colony", "Single cell", "Tissue", "Organ"],
      "Volvox is a hollow ball of many similar cells joined together, a colony. Chlamydomonas, its relative, is a single cell."),
    S(0, 2, "Monera", "Bacteria differ from Amoeba in lacking:",
      ["A nuclear membrane", "Cytoplasm", "Ribosomes", "A cell membrane"],
      "Bacteria are prokaryotes: their DNA lies free in the cytoplasm with no membrane round it. They do have cytoplasm, ribosomes and a cell membrane."),
    S(0, 3, "Adaptation", "Bats in a Nigerian cave rest by day and hunt insects at night. This is an example of:",
      ["A behavioural adaptation", "A structural adaptation", "A functional adaptation", "A change of body colour"],
      "Being active at night is something the animal does, so it is behavioural. A structural adaptation is a body part, such as the wing membrane, and a functional one is a body process."),
    S(0, 2, "Evolutionary trends", "Which trend is seen as plants move from algae to flowering plants?",
      ["Less dependence on water for fertilisation", "More dependence on water for fertilisation", "A shift from sporophyte to gametophyte", "Loss of vascular tissue"],
      "Algae and mosses need water for sperm to swim; flowering plants use pollen tubes. The sporophyte, not the gametophyte, becomes the dominant stage."),
    S(0, 3, "Fungi", "Unlike green plants, fungi:",
      ["Cannot make their own food", "Have no cell walls", "Never form spores", "Lack a true nucleus in each cell"],
      "Fungi have no chlorophyll, so they feed as saprophytes or parasites. They have walls (of chitin), true nuclei and usually reproduce by spores."),
]
